import React, { useState } from 'react';
import './index.css';
import { Header } from './components/Header';
import { CategorySelector } from './components/CategorySelector';
import { ModeSelector } from './components/ModeSelector';
import { GameBoard } from './components/GameBoard';
import { VotingPanel } from './components/VotingPanel';
import { Category, GameMode, Puzzle } from './types';
import { gameService } from './lib/gameService';

type AppState = 'category' | 'mode' | 'playing' | 'voting' | 'results';

function App() {
  const [state, setState] = useState<AppState>('category');
  const [category, setCategory] = useState<Category | null>(null);
  const [mode, setMode] = useState<GameMode | null>(null);
  const [puzzle, setPuzzle] = useState<Puzzle | null>(null);
  const [loading, setLoading] = useState(false);
  const [startTime, setStartTime] = useState<number>(0);
  const [gameResult, setGameResult] = useState<{
    won: boolean;
    filledSlots: (string | null)[];
    incorrectCount: number;
    timeSpent: number;
  } | null>(null);

  const handleCategorySelect = (selected: Category) => {
    setCategory(selected);
    setState('mode');
  };

  const handleModeSelect = async (selected: GameMode) => {
    setMode(selected);
    setLoading(true);
    try {
      if (category) {
        const dailyPuzzle = await gameService.getDailyPuzzle(category, selected);
        setPuzzle(dailyPuzzle);
        setStartTime(Date.now());
        setState('playing');
      }
    } catch (error) {
      console.error('Failed to load puzzle:', error);
      alert('Failed to load puzzle. Please try again.');
      setState('category');
    } finally {
      setLoading(false);
    }
  };

  const handleGameOver = async (won: boolean, filledSlots: (string | null)[], incorrectCount: number) => {
    if (!puzzle || !mode) return;

    const timeSpent = Math.floor((Date.now() - startTime) / 1000);
    
    try {
      await gameService.submitGameResult(puzzle.id, {
        mode,
        filledSlots,
        incorrectCount,
        timeSpent,
        won
      });
      
      setGameResult({ won, filledSlots, incorrectCount, timeSpent });
      
      if (won) {
        setState('voting');
      } else {
        setState('results');
      }
    } catch (error) {
      console.error('Failed to save result:', error);
      setState('results');
    }
  };

  const handleVoteComplete = () => {
    setState('results');
  };

  const handlePlayAgain = () => {
    setState('category');
    setCategory(null);
    setMode(null);
    setPuzzle(null);
    setGameResult(null);
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-gray-50 to-gray-100">
      <Header />
      
      <main className="max-w-6xl mx-auto px-4 py-12">
        {state === 'category' && <CategorySelector onSelect={handleCategorySelect} />}

        {state === 'mode' && <ModeSelector onSelect={handleModeSelect} />}

        {state === 'playing' && puzzle && !loading && (
          <GameBoard
            puzzle={puzzle}
            mode={mode!}
            onGuess={() => {}}
            onGameOver={handleGameOver}
          />
        )}

        {state === 'voting' && puzzle && gameResult?.won && (
          <div>
            <h2 className="text-2xl font-bold mb-4 text-center">Great job! 🎉</h2>
            <VotingPanel
              puzzleId={puzzle.id}
              wordA={puzzle.traits?.[0]?.keyword || 'word1'}
              wordB={puzzle.traits?.[1]?.keyword || 'word2'}
              onVoteSubmitted={handleVoteComplete}
            />
          </div>
        )}

        {state === 'results' && gameResult && (
          <div className="text-center max-w-2xl mx-auto bg-white p-8 rounded-lg shadow-lg">
            {gameResult.won ? (
              <>
                <h2 className="text-3xl font-bold mb-4">🎉 You Won!</h2>
                <p className="text-lg text-gray-600 mb-2">
                  Time: {Math.floor((Date.now() - startTime) / 1000)}s
                </p>
                <p className="text-lg text-gray-600 mb-6">
                  Incorrect guesses: {gameResult.incorrectCount}/5
                </p>
              </>
            ) : (
              <>
                <h2 className="text-3xl font-bold mb-4">💥 Game Over</h2>
                <p className="text-lg text-gray-600 mb-2">
                  Better luck next time!
                </p>
                <p className="text-lg text-gray-600 mb-6">
                  The answer was: <span className="font-bold">{puzzle?.answer}</span>
                </p>
              </>
            )}
            <button
              onClick={handlePlayAgain}
              className="px-8 py-3 bg-blue-600 text-white rounded-lg font-bold text-lg hover:bg-blue-700"
            >
              Play Again
            </button>
          </div>
        )}

        {loading && (
          <div className="text-center">
            <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            <p className="mt-4 text-lg text-gray-600">Loading puzzle...</p>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
